    a: 'b',
    r: 'The information or appraisal ratio looks at the amount of excess return relative to the excess risk. When comparing two portfolios with positive alpha, the appraisal ratio compares the alpha per unit of excess risk. A higher information ratio suggests the manager is generating more outperformance per unit of excess risk taken.',
