    q: 'A calculation question is consuming time and the candidate has two minutes invested. What is the recommended action?',
    o: ['Mark it, move on, and return on a second pass', 'Guess immediately and move on', 'Skip the rest of the section', 'Continue until it is solved, since the marks are equal'],
    a: 'a',
    r: 'Leave the hardest calculation for a second pass. Mark it, move on, and return. Two minutes lost on one question costs two easier questions, and every question carries the same mark.',
