    q: 'What should a candidate note first when reading a case study?',
    o: ['The names of the parties', 'The client\'s objective, horizon, risk tolerance and any constraint', 'The currency of the transaction', 'The date of the scenario'],
    a: 'b',
    r: 'Read the scenario once and note the client\'s objective, horizon, risk tolerance and any constraint — the questions usually turn on one of those.',
