    o: ['Coral Shipping, because it has the highest coupon and the shortest maturity.', 'Alpine Telecom, because it has the longest maturity (8 years) and the lowest coupon (3%), making it the most sensitive to interest-rate changes.', 'Beacon Foods, because its yield equals its coupon so it trades at par.', 'Coral Shipping, because its yield is below its coupon so it trades at a discount.'],
